alter table public.users enable row level security; alter table public.school_years enable row level security; alter table public.blocks enable row level security; alter table public.teachers enable row level security; alter table public.students enable row level security; alter table public.club_offerings enable row level security; alter table public.student_submissions enable row level security; alter table public.student_interest_ratings enable row level security; alter table public.club_validation_issues enable row level security; alter table public.student_validation_issues enable row level security; alter table public.match_runs enable row level security; alter table public.draft_assignments enable row level security; alter table public.match_demand_summaries enable row level security; alter table public.below_minimum_decisions enable row level security; alter table public.final_assignments enable row level security; alter table public.history_snapshots enable row level security; alter table public.history_student_outcomes enable row level security;
create or replace function public.current_role() returns app_role language sql stable security definer set search_path=public as $$ select role from public.users where id=auth.uid() and is_active=true $$;
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$ select public.current_role()='admin' $$;
create policy "users self or admin select" on public.users for select using (id=auth.uid() or public.is_admin());
create policy "admin all users" on public.users for all using (public.is_admin()) with check (public.is_admin());
create policy "admin all school_years" on public.school_years for all using(public.is_admin()) with check(public.is_admin()); create policy "signed read school_years" on public.school_years for select using(auth.uid() is not null);
create policy "admin all blocks" on public.blocks for all using(public.is_admin()) with check(public.is_admin()); create policy "signed read blocks" on public.blocks for select using(auth.uid() is not null);
create policy "admin all teachers" on public.teachers for all using(public.is_admin()) with check(public.is_admin()); create policy "signed read teachers" on public.teachers for select using(auth.uid() is not null);
create policy "admin all students" on public.students for all using(public.is_admin()) with check(public.is_admin()); create policy "student own roster" on public.students for select using(linked_user_id=auth.uid() or lower(student_email)=lower((select email from public.users where id=auth.uid())) or public.is_admin());
create policy "admin all clubs" on public.club_offerings for all using(public.is_admin()) with check(public.is_admin()); create policy "teacher own clubs" on public.club_offerings for all using(submitted_by_user_id=auth.uid() or public.is_admin()) with check(submitted_by_user_id=auth.uid() or public.is_admin()); create policy "students read visible clubs" on public.club_offerings for select using(is_active and show_to_students and auth.uid() is not null);
create policy "admin validations" on public.club_validation_issues for all using(public.is_admin()) with check(public.is_admin()); create policy "admin student validations" on public.student_validation_issues for all using(public.is_admin()) with check(public.is_admin());
create policy "admin submissions" on public.student_submissions for all using(public.is_admin()) with check(public.is_admin()); create policy "student own submissions" on public.student_submissions for all using(submitted_by_user_id=auth.uid() or public.is_admin()) with check(submitted_by_user_id=auth.uid() or public.is_admin());
create policy "ratings via own submission" on public.student_interest_ratings for all using(public.is_admin() or exists(select 1 from public.student_submissions s where s.id=student_submission_id and s.submitted_by_user_id=auth.uid())) with check(public.is_admin() or exists(select 1 from public.student_submissions s where s.id=student_submission_id and s.submitted_by_user_id=auth.uid()));
create policy "admin match" on public.match_runs for all using(public.is_admin()) with check(public.is_admin()); create policy "admin draft" on public.draft_assignments for all using(public.is_admin()) with check(public.is_admin()); create policy "admin demand" on public.match_demand_summaries for all using(public.is_admin()) with check(public.is_admin()); create policy "admin decisions" on public.below_minimum_decisions for all using(public.is_admin()) with check(public.is_admin());
create policy "admin final" on public.final_assignments for all using(public.is_admin()) with check(public.is_admin()); create policy "teacher final read own" on public.final_assignments for select using(exists(select 1 from public.club_offerings c where c.id=club_offering_id and c.submitted_by_user_id=auth.uid())); create policy "student final read own" on public.final_assignments for select using(exists(select 1 from public.students s where s.id=student_id and (s.linked_user_id=auth.uid() or lower(s.student_email)=lower((select email from public.users where id=auth.uid())))));
create policy "admin history" on public.history_snapshots for all using(public.is_admin()) with check(public.is_admin()); create policy "admin history outcomes" on public.history_student_outcomes for all using(public.is_admin()) with check(public.is_admin());
